SELECT
  *,
  accurateCast(byteSize(*) + byteSize(toUInt32(0)), 'UInt32') AS total_event_size
FROM
  (
    SELECT
      uuid,
      event,
      ifNull(typed_properties, defaultValueOfArgumentType(assumeNotNull(typed_properties))) AS properties,
      timestamp,
      team_id,
      distinct_id,
      elements_chain,
      created_at,
      person_id,
      ifNull(
        typed_person_properties,
        defaultValueOfArgumentType(assumeNotNull(typed_person_properties))
      ) AS person_properties,
      if(
        isNull(typed_properties),
        source.properties,
        JSONExtractString(cleaned_properties, '$unparseable_properties')
      ) AS _unparseable_properties,
      if(
        isNull(typed_person_properties),
        source.person_properties,
        JSONExtractString(cleaned_person_properties, '$unparseable_properties')
      ) AS _unparseable_person_properties,
      _active_feature_flags,
      person_created_at,
      group0_properties,
      group1_properties,
      group2_properties,
      group3_properties,
      group4_properties,
      group0_created_at,
      group1_created_at,
      group2_created_at,
      group3_created_at,
      group4_created_at,
      person_mode,
      historical_migration,
      coalesce(captured_at, created_at) AS captured_at,
      _timestamp,
      _offset,
      _partition,
      arrayMap(
        i -> (_headers.value[i]),
        arrayFilter(
          i -> ((_headers.name[i]) = 'kafka-consumer-breadcrumbs'),
          arrayEnumerate(_headers.name)
        )
      ) AS consumer_breadcrumbs
    FROM posthog.kafka_events_json_native_json AS source
  );
CREATE MATERIALIZED VIEW posthog.kafka_logs34_avro_mv TO posthog.writable_logs34 (uuid String, trace_id String, span_id String, trace_flags Int32, timestamp DateTime64(6), observed_timestamp DateTime64(6), body String, severity_text String, severity_number Int32, service_name String, instrumentation_scope String, event_name String, attributes_map_str Map(String, String), resource_attributes Map(String, String), team_id Int32, original_expiry_timestamp DateTime64(6), _partition UInt64, _topic LowCardinality(String), _offset UInt64, _record_count Int64, _bytes_uncompressed Nullable(Int64), _bytes_compressed Nullable(Int64), pattern String, pattern_version UInt8) AS SELECT
  uuid,
  trace_id,
  span_id,
  trace_flags,
  timestamp,
  observed_timestamp,
  body,
  severity_text,
  severity_number,
  service_name,
  instrumentation_scope,
  event_name,
  mapSort(mapApply((k, v) -> (concat(k, '__str'), JSONExtractString(v)), attributes)) AS attributes_map_str,
  mapSort(mapApply((k, v) -> (k, JSONExtractString(v)), resource_attributes)) AS resource_attributes,
  toInt32OrZero(_headers.value[indexOf(_headers.name, 'team_id')]) AS team_id,
  observed_timestamp
  + toIntervalDay(
    if(
      (retention_days IS NOT NULL) AND (retention_days > 0),
      retention_days,
      toInt32OrDefault(_headers.value[indexOf(_headers.name, 'retention-days')], toInt32(15))
    )
  ) AS original_expiry_timestamp,
  _partition,
  _topic,
  _offset,
  toInt64OrDefault(_headers.value[indexOf(_headers.name, 'record_count')], toInt64(1)) AS _record_count,
  toInt64OrNull(_headers.value[indexOf(_headers.name, 'bytes_uncompressed')]) / _record_count AS _bytes_uncompressed,
  toInt64OrNull(_headers.value[indexOf(_headers.name, 'bytes_compressed')]) / _record_count AS _bytes_compressed,
  ifNull(pattern, '') AS pattern,
  toUInt8(ifNull(pattern_version, 0)) AS pattern_version
FROM posthog.kafka_logs_avro;
